    "title": "Receive",
    "category": "Multichain",
    "markup": "<div class=\"modal fixed-header\" id=\"multichainReceiveModal\">\n        <div class=\"modal-header\">\n          <button class=\"back-button\" id=\"closeMultichainReceiveModal\"></button>\n          <div class=\"modal-title\" id=\"multichainReceiveTitle\">Receive</div>\n        </div>\n        <div class=\"modal-content\">\n          <div class=\"multichain-screen\" id=\"multichainReceiveBody\"></div>\n        </div>\n        <a class=\"last-item\" href=\"#\"> </a>\n      </div>"
